			entry:   transactionalEntry("erp-sync", "erp-sync", "erp-source", "orders-source"),
			wantErr: `duplicate connector "orders-source"`,
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
