	t.Run("topic-bearing system assembles; the host template supplies contracts", func(t *testing.T) {
		model, err := Assemble([]template.ScaffoldEntry{
			extractorEntry("order-extractor", "order-extractor", "orders", "Order"),
		}, discardWarnf)
		if err != nil {
